/** Shared transport contract for Gram, Lyra, and other Oberon clients. */

export interface OberonBlobRef {
  sha256: string;
  sizeBytes: number;
  contentType: string;
}

export interface OberonChangeEnvelope {
  /** Stable idempotency key generated by the client before its first upload attempt. */
  changeId: string;
  /** Namespaced type such as `gram.chat.message` or `gram.work.checkpoint`. */
  entityType: string;
  entityId: string;
  operation: 'upsert' | 'delete';
  /** Client revision for this entity. */
  entityRevision: number;
  /** Cloud revision this mutation was based on; used for conflict detection. */
  baseRevision: number;
  occurredAt: string;
  payload?: unknown;
  blobs?: OberonBlobRef[];
}

export interface OberonPushChangesRequest {
  /** Registered application and device identifiers; account identity comes from auth. */
  appId: string;
  deviceId: string;
  changes: OberonChangeEnvelope[];
}

export interface OberonConflict {
  conflictId: string;
  changeId: string;
  entityType: string;
  entityId: string;
  baseRevision: number;
  currentRevision: number;
  currentPayload?: unknown;
  reason: 'revision_mismatch' | 'concurrent_delete' | 'base_commit_changed' | 'validation_failed';
}

export interface OberonPushChangesResponse {
  acceptedChangeIds: string[];
  cursor: string;
  conflicts: OberonConflict[];
  missingBlobs: OberonBlobRef[];
}

export interface OberonPullChangesResponse {
  cursor: string;
  hasMore: boolean;
  changes: OberonChangeEnvelope[];
}

export interface OberonSyncTransport {
  push(request: OberonPushChangesRequest, signal?: AbortSignal): Promise<OberonPushChangesResponse>;
  pull(params: {
    appId: string;
    deviceId: string;
    cursor: string;
    limit?: number;
  }, signal?: AbortSignal): Promise<OberonPullChangesResponse>;
  uploadBlob(ref: OberonBlobRef, bytes: Uint8Array, signal?: AbortSignal): Promise<void>;
  downloadBlob(ref: OberonBlobRef, signal?: AbortSignal): Promise<Uint8Array>;
}
